const CACHE='nexus-workspace-v22';const ASSETS=["./certificate-layout.js?v=2.2", "./workspace-core.js?v=2.2", "./manifest.webmanifest", "./index.html", "./checklisten.js?v=2.2", "./nexus-logo.png", "./entwuerfe.html", "./zeugnis.css?v=2.2", "./register.js?v=2.2", "./workspace.css?v=2.2", "./entwuerfe.js?v=2.2", "./evaluation-backup.js?v=2.2", "./zeugnis.js?v=2.2", "./zeugnis-output.js?v=2.2", "./output.js?v=2.2", "./docx.iife.js?v=2.2", "./certificate-features.js?v=2.2", "./zeugnis-letter.js?v=2.2", "./process-templates.js?v=2.2", "./jspdf.umd.min.js?v=2.2", "./home.css?v=2.2", "./nexus-logo.svg", "./mobile.css?v=2.2", "./workflow.js?v=2.2", "./navigation.js?v=2.2", "./module-adapters.js?v=2.2", "./navigation.css?v=2.2", "./certificate-word.js?v=2.2", "./tools/exit.html", "./tools/zeugnis.html", "./tools/protokoll.html", "./tools/checklisten.html", "./tools/bewertung.html", "./fonts/LICENSE-Liberation.txt", "./fonts/certificate-fonts.json", "./icons/icon-180.png", "./icons/icon-512.png", "./icons/icon-192.png"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('nexus-workspace-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const req=event.request,url=new URL(req.url);if(req.method!=='GET'||url.origin!==self.location.origin||!req.url.startsWith(self.registration.scope))return;if(req.mode==='navigate'){event.respondWith(fetch(req).then(response=>{if(response.ok){const key=new URL(req.url);key.search='';const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(key.href,copy));}return response;}).catch(()=>caches.open(CACHE).then(cache=>cache.match(req,{ignoreSearch:true}))));}else event.respondWith(caches.open(CACHE).then(cache=>cache.match(req).then(hit=>hit||fetch(req))));});
